// Agrega todas as linhas do BigQuery em um único objeto JSON
const rows = $input.all().map(item => ({
  BU:                      item.json.BU                     ?? null,
  Product:                 item.json.Product                 ?? null,
  Macro_BU:                item.json.Macro_BU                ?? null,
  MES:                     item.json.MES                     ?? null,
  ANO:                     item.json.ANO                     ?? null,
  QUARTER:                 item.json.QUARTER                 ?? null,
  MNG_1:                   item.json.MNG_1                   ?? null,
  MNG_2:                   item.json.MNG_2                   ?? null,
  MNG_3:                   item.json.MNG_3                   ?? null,
  MNG_4:                   item.json.MNG_4                   ?? null,
  Cenario:                 item.json.Cenario                 ?? null,
  DICCIONARIO_LOCAL_EBIT:  item.json.DICCIONARIO_LOCAL_EBIT  ?? null,
  Value: typeof item.json.Value === 'string'
           ? parseFloat(item.json.Value)
           : (item.json.Value ?? 0)
}));

const now = new Date();
const lastUpdated = now.toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit'
});

return [{ json: {
  last_updated: lastUpdated,
  row_count: rows.length,
  data: rows
} }];
